   private RetCode CDLSEPARATINGLINES_OpenBody( CDLSEPARATINGLINES_Stream sp, double[] inOpen, double[] inHigh, double[] inLow, double[] inClose, int startIdx )
   {
      int[] sink_outInteger = new int[1];
      return CDLSEPARATINGLINES_OpenCore( sp, inOpen, inHigh, inLow, inClose, startIdx, out _, out _, sink_outInteger, 0 );
   }

   private RetCode CDLSEPARATINGLINES_OpenAndFillBody( CDLSEPARATINGLINES_Stream sp, double[] inOpen, double[] inHigh, double[] inLow, double[] inClose, out int outBegIdx, out int outNBElement, int[] outInteger )
   {
      outBegIdx = 0;
      outNBElement = 0;
      if( ReferenceEquals(outInteger, inOpen) || ReferenceEquals(outInteger, inHigh) || ReferenceEquals(outInteger, inLow) || ReferenceEquals(outInteger, inClose) ) {
         return RetCode.BadParam;
      }
      return CDLSEPARATINGLINES_OpenCore( sp, inOpen, inHigh, inLow, inClose, 0, out outBegIdx, out outNBElement, outInteger, 1 );
   }

   private RetCode CDLSEPARATINGLINES_OpenAndFillInternalBody( CDLSEPARATINGLINES_Stream sp, double[] inOpen, double[] inHigh, double[] inLow, double[] inClose, int startIdx, out int outBegIdx, out int outNBElement, int[] outInteger )
   {
      return CDLSEPARATINGLINES_OpenCore(sp, inOpen, inHigh, inLow, inClose, startIdx, out outBegIdx, out outNBElement, outInteger, 1);
   }

   /* CDLSEPARATINGLINES_OpenAndFill anchored at startIdx — the composed-open fusion seam. */
   internal CDLSEPARATINGLINES_Stream CDLSEPARATINGLINES_OpenAndFillInternal( double[] inOpen, double[] inHigh, double[] inLow, double[] inClose, int startIdx, out int outBegIdx, out int outNBElement, int[] outInteger )
   {
      CDLSEPARATINGLINES_Stream sp = new CDLSEPARATINGLINES_Stream(this);
      RetCode retCode = CDLSEPARATINGLINES_OpenAndFillInternalBody(sp, inOpen, inHigh, inLow, inClose, startIdx, out outBegIdx, out outNBElement, outInteger);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      throw StreamFailure("CDLSEPARATINGLINES", "openAndFill", retCode);
   }

   /* Internal startIdx-anchored open behind CDLSEPARATINGLINES_Open (composition seam). */
   internal CDLSEPARATINGLINES_Stream CDLSEPARATINGLINES_OpenInternal( double[] inOpen, double[] inHigh, double[] inLow, double[] inClose, int startIdx )
   {
      CDLSEPARATINGLINES_Stream sp = new CDLSEPARATINGLINES_Stream(this);
      RetCode retCode = CDLSEPARATINGLINES_OpenBody(sp, inOpen, inHigh, inLow, inClose, startIdx);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      throw StreamFailure("CDLSEPARATINGLINES", "open", retCode);
   }

   /// <summary>Open a live <c>CDLSEPARATINGLINES</c> stream over the warm-up history.</summary>
   /// <remarks>
   /// <para>The handle's <see cref="CDLSEPARATINGLINES_Stream.Value"/> starts at the
   /// last history bar's value — bit-identical to what <c>CDLSEPARATINGLINES</c>
   /// reports for that bar.</para>
   /// <para>The history must hold at least <c>CDLSEPARATINGLINES_Lookback(...) + 1</c>
   /// bars (unstable-period aware). Nothing is written to any caller array; use
   /// <c>CDLSEPARATINGLINES_OpenAndFill</c> to get the warm-up values as well.</para>
   /// </remarks>
   /// <param name="inOpen">Open price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inHigh">High price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inLow">Low price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inClose">Close price of each bar. The warm-up history, oldest bar first.</param>
   /// <returns>The open stream handle.</returns>
   /// <exception cref="InsufficientHistoryException">The history holds fewer than <c>CDLSEPARATINGLINES_Lookback(...) + 1</c>
   /// bars.</exception>
   /// <exception cref="System.ArgumentException">An optional parameter is outside its documented range, or the input series
   /// have different lengths.</exception>
   /// <exception cref="System.ArgumentNullException">An input array is null.</exception>
   public CDLSEPARATINGLINES_Stream CDLSEPARATINGLINES_Open( double[] inOpen, double[] inHigh, double[] inLow, double[] inClose )
   {
      ArgumentNullException.ThrowIfNull(inOpen);
      ArgumentNullException.ThrowIfNull(inHigh);
      ArgumentNullException.ThrowIfNull(inLow);
      ArgumentNullException.ThrowIfNull(inClose);
      return CDLSEPARATINGLINES_OpenInternal(inOpen, inHigh, inLow, inClose, 0);
   }

   /// <summary><c>CDLSEPARATINGLINES_Open</c> that also fills the output array(s) over
   /// the whole history in the same single pass.</summary>
   /// <remarks>
   /// <para>The values written are bit-identical to what <c>CDLSEPARATINGLINES</c>
   /// produces over the same series, so no separate batch call is needed for the
   /// warm-up plot.</para>
   /// <para>Output arrays must hold <c>historyLen -
   /// CDLSEPARATINGLINES_Lookback(...)</c> values and must not alias the inputs
   /// or each other — this path writes the outputs and then reads the input tail
   /// to seed its rings, so the batch tier's in-place allowance does not carry
   /// over here.</para>
   /// <para>The range written is reported on the returned handle:
   /// <see cref="CDLSEPARATINGLINES_Stream.FillRange"/>.</para>
   /// </remarks>
   /// <param name="inOpen">Open price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inHigh">High price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inLow">Low price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inClose">Close price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="outInteger">+100 for a bullish (white second candle) hit, -100 for a bearish (black
   /// second candle) hit, 0 otherwise. Must hold at least <c>historyLen -
   /// CDLSEPARATINGLINES_Lookback(...)</c> values.</param>
   /// <returns>The open stream handle, with its fill range set.</returns>
   /// <exception cref="InsufficientHistoryException">The history holds fewer than <c>CDLSEPARATINGLINES_Lookback(...) + 1</c>
   /// bars.</exception>
   /// <exception cref="System.ArgumentException">An optional parameter is outside its documented range, the input series
   /// have different lengths, or an output array aliases an input or another
   /// output.</exception>
   /// <exception cref="System.ArgumentNullException">An input or output array is null.</exception>
   public CDLSEPARATINGLINES_Stream CDLSEPARATINGLINES_OpenAndFill( double[] inOpen, double[] inHigh, double[] inLow, double[] inClose, int[] outInteger )
   {
      ArgumentNullException.ThrowIfNull(inOpen);
      ArgumentNullException.ThrowIfNull(inHigh);
      ArgumentNullException.ThrowIfNull(inLow);
      ArgumentNullException.ThrowIfNull(inClose);
      ArgumentNullException.ThrowIfNull(outInteger);
      CDLSEPARATINGLINES_Stream sp = new CDLSEPARATINGLINES_Stream(this);
      RetCode retCode = CDLSEPARATINGLINES_OpenAndFillBody(sp, inOpen, inHigh, inLow, inClose, out int outBegIdx, out int outNBElement, outInteger);
      sp.fillRange = new OutRange(outBegIdx, outNBElement);
      if( retCode == RetCode.Success ) {
         return sp;
      }
      throw StreamFailure("CDLSEPARATINGLINES", "openAndFill", retCode);
   }
}
